import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import './CSS/Products.css';

const Products = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [selectedSubCategory, setSelectedSubCategory] = useState('All');

  const categoryScrollRef = useRef(null);
  const rowScrollRefs = useRef({});
  
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [activeModalImage, setActiveModalImage] = useState('');
  const [quantity, setQuantity] = useState(1);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4000/api/seller/products');
      
      if (Array.isArray(response.data)) {
        setProducts(response.data);
      } else if (response.data && Array.isArray(response.data.products)) {
        setProducts(response.data.products);
      } else {
        setProducts([]);
      }
    } catch (err) {
      console.error('Error fetching products:', err);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const scrollCategories = (direction) => {
    if (categoryScrollRef.current) {
      const { scrollLeft, clientWidth } = categoryScrollRef.current;
      const scrollAmount = clientWidth * 0.5;
      categoryScrollRef.current.scrollTo({
        left: direction === 'left' ? scrollLeft - scrollAmount : scrollLeft + scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  const scrollRow = (subCatName, direction) => {
    const rowRef = rowScrollRefs.current[subCatName];
    if (rowRef) {
      const scrollAmount = 300;
      rowRef.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth'
      });
    }
  };

  const categories = ['All', 'Electronics', 'Fashion', 'Home & Kitchen', 'Furnitures'];

  const electronicsSubCategories = [
    { 
      id: 1, 
      name: 'All', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="3" y="3" width="7" height="7" rx="2" fill="currentColor" fillOpacity="0.2" stroke="currentColor" strokeWidth="2"/>
          <rect x="14" y="3" width="7" height="7" rx="2" fill="currentColor" stroke="currentColor" strokeWidth="2"/>
          <rect x="14" y="14" width="7" height="7" rx="2" fill="currentColor" fillOpacity="0.2" stroke="currentColor" strokeWidth="2"/>
          <rect x="3" y="14" width="7" height="7" rx="2" fill="currentColor" stroke="currentColor" strokeWidth="2"/>
        </svg>
      )
    },
    { 
      id: 2, 
      name: 'Smartphone', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="5" y="2" width="14" height="20" rx="3" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <line x1="10" y1="5" x2="14" y2="5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <circle cx="12" cy="18" r="1" fill="currentColor"/>
        </svg>
      )
    },
    { 
      id: 3, 
      name: 'Laptop', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="4" width="20" height="13" rx="2" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <path d="M2 19H22" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M6 15H18" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" opacity="0.5"/>
        </svg>
      )
    },
    { 
      id: 4, 
      name: 'Earpods', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M4 15V13C4 8.58172 7.58172 5 12 5C16.4183 5 20 8.58172 20 13V15" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <rect x="2" y="14" width="4" height="6" rx="2" fill="currentColor" fillOpacity="0.3" stroke="currentColor" strokeWidth="2"/>
          <rect x="18" y="14" width="4" height="6" rx="2" fill="currentColor" fillOpacity="0.3" stroke="currentColor" strokeWidth="2"/>
        </svg>
      )
    },
    { 
      id: 5, 
      name: 'Smartwatch', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="8" y="6" width="8" height="12" rx="3" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <path d="M9 2V6" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M15 2V6" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M9 18V22" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M15 18V22" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
        </svg>
      )
    },
    { 
      id: 6, 
      name: 'Tablets', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="4" y="2" width="16" height="20" rx="2" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <circle cx="12" cy="18" r="1" fill="currentColor"/>
        </svg>
      )
    },
    { 
      id: 7, 
      name: 'PC accessories', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="7" width="20" height="11" rx="2" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <path d="M6 11H8" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M11 11H13" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M16 11H18" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M9 15H15" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
        </svg>
      )
    },
    { 
      id: 8, 
      name: 'Desktop', 
      svg: (
        <svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect x="2" y="3" width="20" height="13" rx="2" fill="currentColor" fillOpacity="0.15" stroke="currentColor" strokeWidth="2"/>
          <path d="M8 21H16" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          <path d="M12 16V21" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
        </svg>
      )
    }
  ];

  // Specific categorized rows for the Smartphone section view
  const smartphoneRowCategories = [
    { id: 'sc1', name: '🔥 Trending Smartphones', keywords: ['5g', 'galaxy', 'iphone', 'pixel', 'a36', 'a54'] },
    { id: 'sc2', name: '👑 Flagship & Pro Devices', keywords: ['ultra', 'pro', 'iphone', 'fold', 'flip'] },
    { id: 'sc3', name: '⚡ Budget & Mid-Range', keywords: ['redmi', 'oneplus', 'samsung a', 'nord', 'realme', 'vivo', 'oppo', 'poco'] }
  ];

  const synonymMap = {
    'smartphone': ['smartphone', 'mobile', 'cellphone', 'iphone', 'galaxy', 'pixel', 'redmi', 'oneplus', 'samsung', 'realme', 'vivo', 'oppo', 'xiaomi', 'poco', 'iqoo', 'motorola', 'moto', 'nokia', 'asus'],
    'laptop': ['laptop', 'notebook', 'macbook', 'thinkpad', 'chromebook'],
    'earpods': ['earpod', 'earphone', 'earbud', 'airpod', 'headphone', 'headset', 'rockerz'],
    'smartwatch': ['smartwatch', 'watch', 'band', 'wearable'],
    'tablets': ['tablet', 'ipad', 'tab'],
    'pc accessories': ['accessory', 'accessories', 'keyboard', 'mouse', 'mousepad', 'hub', 'adapter'],
    'desktop': ['desktop', 'pc', 'cpu', 'imac', 'tower', 'workstation']
  };

  const filteredProducts = products.filter((product) => {
    const matchesMain = selectedCategory === 'All' || product.category?.toLowerCase() === selectedCategory.toLowerCase();
    
    let matchesSub = true;
    if (selectedCategory.toLowerCase() === 'electronics' && selectedSubCategory !== 'All' && selectedSubCategory !== 'Smartphone') {
      const subCatTarget = selectedSubCategory.toLowerCase();
      const pTitle = (product.title || product.name || '').toLowerCase();
      const pSubCat = (product.subCategory || '').toLowerCase();

      const keywords = synonymMap[subCatTarget] || [subCatTarget];
      matchesSub = keywords.some(keyword => 
        pSubCat.includes(keyword) || pTitle.includes(keyword)
      );
    }

    return matchesMain && matchesSub;
  });

  const handleMainCategoryClick = (cat) => {
    setSelectedCategory(cat);
    setSelectedSubCategory('All');
  };

  const resolveImageSrc = (rawImage) => {
    if (!rawImage) return 'https://via.placeholder.com/200';
    const cleanPath = String(rawImage).replace(/\\/g, '/');

    if (cleanPath.startsWith('http://') || cleanPath.startsWith('https://')) {
      return cleanPath;
    } else if (cleanPath.startsWith('/uploads')) {
      return `http://localhost:4000${cleanPath}`;
    } else if (cleanPath.startsWith('uploads')) {
      return `http://localhost:4000/${cleanPath}`;
    } else {
      return `http://localhost:4000/uploads/${cleanPath}`;
    }
  };

  const handleAddToCart = (product, itemQty = 1, e) => {
    if (e) e.stopPropagation();

    const cartItem = {
      _id: product._id || product.id,
      title: product.title || product.name,
      price: Number(product.price),
      image: resolveImageSrc(product.images?.[0] || product.imageUrl || product.image),
      category: product.category,
      quantity: itemQty
    };

    const existingCart = JSON.parse(localStorage.getItem('cartItems')) || [];
    const existingIndex = existingCart.findIndex((item) => item._id === cartItem._id);

    if (existingIndex > -1) {
      existingCart[existingIndex].quantity += itemQty;
    } else {
      existingCart.push(cartItem);
    }

    localStorage.setItem('cartItems', JSON.stringify(existingCart));
    window.dispatchEvent(new Event('cartUpdated'));

    alert(`${cartItem.title} added to cart!`);
    
    if (selectedProduct) {
      setSelectedProduct(null);
    }
  };

  const handleOpenModal = (item) => {
    setSelectedProduct(item);
    setQuantity(1);
    
    let firstImg = 'https://via.placeholder.com/200';
    if (item.images && item.images.length > 0) {
      firstImg = item.images[0];
    } else if (item.imageUrl || item.image) {
      firstImg = item.imageUrl || item.image;
    }
    setActiveModalImage(resolveImageSrc(firstImg));
  };

  return (
    <div className="products-page">
      <div className="products-header">
        <h1>Explore All Products</h1>
        <p>Discover top-tier mobile devices, wearables, and high-performance tech accessories.</p>
      </div>

      <div className="products-filter-bar">
        {categories.map((cat) => (
          <button
            key={cat}
            className={`filter-btn ${selectedCategory === cat ? 'active' : ''}`}
            onClick={() => handleMainCategoryClick(cat)}
          >
            {cat}
          </button>
        ))}
      </div>

      {selectedCategory.toLowerCase() === 'electronics' && (
        <div className="category-section-container" style={{ position: 'relative', padding: '0 30px' }}>
          <h2 className="category-section-heading">Shop by category</h2>
          
          <button className="cat-scroll-btn cat-left-btn" onClick={() => scrollCategories('left')}>
            &#10094;
          </button>

          <div ref={categoryScrollRef} className="category-scroll-container">
            {electronicsSubCategories.map((subCat) => (
              <div 
                key={subCat.id} 
                className={`category-soft-card ${selectedSubCategory === subCat.name ? 'active' : ''}`}
                onClick={() => setSelectedSubCategory(subCat.name)}
              >
                <div className="soft-card-img-wrapper" style={{ color: selectedSubCategory === subCat.name ? '#6366f1' : '#334155' }}>
                  {subCat.svg}
                </div>
                <span className="soft-card-title">{subCat.name}</span>
                <div className="soft-card-indicator"></div>
              </div>
            ))}
          </div>

          <button className="cat-scroll-btn cat-right-btn" onClick={() => scrollCategories('right')}>
            &#10095;
          </button>
        </div>
      )}

      {/* CASE 1: ELECTRONICS & 'ALL' SELECTED -> RENDER STACKED ROWS FOR ALL SUB-CATEGORIES */}
      {selectedCategory.toLowerCase() === 'electronics' && selectedSubCategory === 'All' ? (
        <div className="electronics-stacked-sections" style={{ width: '100%', marginTop: '30px' }}>
          {loading ? (
            <p>Loading products from database...</p>
          ) : (
            electronicsSubCategories
              .filter((sub) => sub.name !== 'All')
              .map((subCat) => {
                const subCatTarget = subCat.name.toLowerCase();
                const keywords = synonymMap[subCatTarget] || [subCatTarget];

                const rowProducts = products.filter((product) => {
                  const matchesMain = product.category?.toLowerCase() === 'electronics';
                  const pTitle = (product.title || product.name || '').toLowerCase();
                  const pSubCat = (product.subCategory || '').toLowerCase();

                  if (subCatTarget === 'smartphone') {
                    if (
                      pTitle.includes('headphone') || pTitle.includes('earphone') || pTitle.includes('earbud') || 
                      pTitle.includes('rockerz') || pTitle.includes('headset') || pTitle.includes('tab') || pTitle.includes('ipad') ||
                      pSubCat.includes('headphone') || pSubCat.includes('tablet')
                    ) {
                      return false;
                    }
                  }

                  const matchesSub = keywords.some(keyword => 
                    pSubCat.includes(keyword) || pTitle.includes(keyword)
                  );
                  return matchesMain && matchesSub;
                });

                if (rowProducts.length === 0) return null;

                return (
                  <div key={subCat.id} className="category-row-section" style={{ marginBottom: '45px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', padding: '0 30px' }}>
                      <h3 style={{ fontSize: '20px', fontWeight: '800', color: '#0f172a', margin: 0 }}>
                        {subCat.name}
                      </h3>
                      <button 
                        onClick={() => setSelectedSubCategory(subCat.name)}
                        style={{ background: 'none', border: 'none', color: '#6366f1', fontWeight: '700', cursor: 'pointer', fontSize: '14px' }}
                      >
                        See All →
                      </button>
                    </div>

                    <div style={{ position: 'relative', padding: '0 30px' }}>
                      <button className="cat-scroll-btn cat-left-btn" onClick={() => scrollRow(subCat.name, 'left')}>
                        &#10094;
                      </button>

                      <div ref={(el) => (rowScrollRefs.current[subCat.name] = el)} className="category-horizontal-row">
                        {rowProducts.map((item) => {
                          let rawImage = item.images && item.images.length > 0 ? item.images[0] : item.imageUrl || item.image;
                          let imageSrc = resolveImageSrc(rawImage);

                          return (
                            <div 
                              key={item._id || item.id} 
                              className="product-card"
                              onClick={() => handleOpenModal(item)}
                              style={{ cursor: 'pointer', minWidth: '220px', maxWidth: '220px', flexShrink: 0 }}
                            >
                              <div className="image-box" style={{ height: '180px' }}>
                                <img 
                                  src={imageSrc} 
                                  alt={item.title || item.name} 
                                  onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }}
                                  style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                                />
                              </div>
                              <div className="card-details">
                                <span className="card-category">{item.category}</span>
                                <h3 className="card-title" style={{ fontSize: '14px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                  {item.title || item.name}
                                </h3>
                                <div className="card-footer">
                                  <span className="card-rating">★ <span>4.5</span></span>
                                  <strong className="current-price">${item.price}</strong>
                                </div>
                                <button onClick={(e) => handleAddToCart(item, 1, e)} className="add-to-cart-btn" style={{ width: '100%', marginTop: '10px' }}>
                                  Add to Cart
                                </button>
                              </div>
                            </div>
                          );
                        })}
                      </div>

                      <button className="cat-scroll-btn cat-right-btn" onClick={() => scrollRow(subCat.name, 'right')}>
                        &#10095;
                      </button>
                    </div>
                  </div>
                );
              })
          )}
        </div>
      ) : selectedCategory.toLowerCase() === 'electronics' && selectedSubCategory === 'Smartphone' ? (
        /* CASE 2: SMARTPHONE CLICKED -> RENDER STACKED HORIZONTAL ROWS FOR TRENDING & SMARTPHONE CATEGORIES */
        <div className="electronics-stacked-sections" style={{ width: '100%', marginTop: '30px' }}>
          {loading ? (
            <p>Loading smartphone categories...</p>
          ) : (
            smartphoneRowCategories.map((subCat) => {
              const rowProducts = products.filter((product) => {
                const matchesMain = product.category?.toLowerCase() === 'electronics';
                const pTitle = (product.title || product.name || '').toLowerCase();
                const pSubCat = (product.subCategory || '').toLowerCase();

                // Prevent cross-contamination (tablets/headphones)
                if (
                  pTitle.includes('headphone') || pTitle.includes('earphone') || pTitle.includes('earbud') || 
                  pTitle.includes('rockerz') || pTitle.includes('headset') || pTitle.includes('tab') || pTitle.includes('ipad') ||
                  pSubCat.includes('headphone') || pSubCat.includes('tablet')
                ) {
                  return false;
                }

                // Match specific smartphone group keywords
                const matchesGroup = subCat.keywords.some(keyword => 
                  pSubCat.includes(keyword) || pTitle.includes(keyword)
                );
                return matchesMain && matchesGroup;
              });

              if (rowProducts.length === 0) return null;

              return (
                <div key={subCat.id} className="category-row-section" style={{ marginBottom: '45px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', padding: '0 30px' }}>
                    <h3 style={{ fontSize: '20px', fontWeight: '800', color: '#0f172a', margin: 0 }}>
                      {subCat.name}
                    </h3>
                  </div>

                  <div style={{ position: 'relative', padding: '0 30px' }}>
                    <button className="cat-scroll-btn cat-left-btn" onClick={() => scrollRow(subCat.name, 'left')}>
                      &#10094;
                    </button>

                    <div ref={(el) => (rowScrollRefs.current[subCat.name] = el)} className="category-horizontal-row">
                      {rowProducts.map((item) => {
                        let rawImage = item.images && item.images.length > 0 ? item.images[0] : item.imageUrl || item.image;
                        let imageSrc = resolveImageSrc(rawImage);

                        return (
                          <div 
                            key={item._id || item.id} 
                            className="product-card"
                            onClick={() => handleOpenModal(item)}
                            style={{ cursor: 'pointer', minWidth: '220px', maxWidth: '220px', flexShrink: 0 }}
                          >
                            <div className="image-box" style={{ height: '180px' }}>
                              <img 
                                src={imageSrc} 
                                alt={item.title || item.name} 
                                onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }}
                                style={{ width: '100%', height: '100%', objectFit: 'contain' }}
                              />
                            </div>
                            <div className="card-details">
                              <span className="card-category">{item.category}</span>
                              <h3 className="card-title" style={{ fontSize: '14px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                {item.title || item.name}
                              </h3>
                              <div className="card-footer">
                                <span className="card-rating">★ <span>4.5</span></span>
                                <strong className="current-price">${item.price}</strong>
                              </div>
                              <button onClick={(e) => handleAddToCart(item, 1, e)} className="add-to-cart-btn" style={{ width: '100%', marginTop: '10px' }}>
                                Add to Cart
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>

                    <button className="cat-scroll-btn cat-right-btn" onClick={() => scrollRow(subCat.name, 'right')}>
                      &#10095;
                    </button>
                  </div>
                </div>
              );
            })
          )}
        </div>
      ) : (
        /* CASE 3: STANDARD GRID VIEW FOR OTHER SUB-CATEGORIES */
        <div className="products-grid-wrapper" style={{ width: '100%', padding: '0 30px', marginTop: '30px' }}>
          {loading ? (
            <p>Loading products from database...</p>
          ) : filteredProducts.length === 0 ? (
            <p>No products available in this category selection.</p>
          ) : (
            <div className="products-grid">
              {filteredProducts.map((item) => {
                let rawImage = item.images && item.images.length > 0 ? item.images[0] : item.imageUrl || item.image;
                let imageSrc = resolveImageSrc(rawImage);

                return (
                  <div key={item._id || item.id} className="product-card" onClick={() => handleOpenModal(item)} style={{ cursor: 'pointer' }}>
                    <div className="image-box">
                      <img src={imageSrc} alt={item.title || item.name} onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }} />
                    </div>
                    <div className="card-details">
                      <span className="card-category">{item.category}</span>
                      <h3 className="card-title">{item.title || item.name}</h3>
                      <div className="card-footer">
                        <span className="card-rating">★ <span>4.5</span></span>
                        <strong className="current-price">${item.price}</strong>
                      </div>
                      <button onClick={(e) => handleAddToCart(item, 1, e)} className="add-to-cart-btn" style={{ position: 'static', transform: 'none', width: '100%', marginTop: '12px' }}>
                        Add to Cart
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* PRODUCT DETAILS MODAL */}
      {selectedProduct && (
        <div className="product-modal-backdrop" onClick={() => setSelectedProduct(null)} style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', backgroundColor: 'rgba(0, 0, 0, 0.65)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '20px' }}>
          <div className="product-modal-card" onClick={(e) => e.stopPropagation()} style={{ backgroundColor: '#fff', borderRadius: '16px', maxWidth: '800px', width: '100%', maxHeight: '90vh', overflowY: 'auto', padding: '30px', position: 'relative', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)' }}>
            <button onClick={() => setSelectedProduct(null)} style={{ position: 'absolute', top: '16px', right: '20px', background: '#f3f4f6', border: 'none', borderRadius: '50%', width: '36px', height: '36px', fontSize: '20px', fontWeight: 'bold', cursor: 'pointer', color: '#374151' }}>
              &times;
            </button>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px', marginTop: '10px' }}>
              <div>
                <div style={{ width: '100%', height: '280px', borderRadius: '12px', overflow: 'hidden', border: '1px solid #e5e7eb', marginBottom: '12px' }}>
                  <img src={activeModalImage} alt={selectedProduct.title || selectedProduct.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }} />
                </div>

                {selectedProduct.images && selectedProduct.images.length > 1 && (
                  <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '4px' }}>
                    {selectedProduct.images.map((img, idx) => {
                      const fullSrc = resolveImageSrc(img);
                      return (
                        <img key={idx} src={fullSrc} alt={`Thumbnail ${idx}`} onClick={() => setActiveModalImage(fullSrc)} style={{ width: '50px', height: '50px', borderRadius: '6px', objectFit: 'cover', cursor: 'pointer', border: activeModalImage === fullSrc ? '2px solid #130352' : '1px solid #e5e7eb' }} />
                      );
                    })}
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <span style={{ fontSize: '12px', textTransform: 'uppercase', color: '#6b7280', fontWeight: 'bold' }}>
                    {selectedProduct.category} {selectedProduct.brand ? `• ${selectedProduct.brand}` : ''}
                  </span>
                  <h2 style={{ fontSize: '22px', color: '#111827', margin: '4px 0' }}>{selectedProduct.title || selectedProduct.name}</h2>
                </div>

                <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px' }}>
                  <span style={{ fontSize: '24px', fontWeight: 'bold', color: '#130352' }}>${selectedProduct.price}</span>
                  {selectedProduct.mrp && <span style={{ fontSize: '16px', color: '#9ca3af', textDecoration: 'line-through' }}>${selectedProduct.mrp}</span>}
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', margin: '10px 0' }}>
                  <div style={{ display: 'flex', alignItems: 'center', border: '1px solid #d1d5db', borderRadius: '6px' }}>
                    <button onClick={() => setQuantity(prev => Math.max(1, prev - 1))} style={{ padding: '6px 12px', border: 'none', background: 'transparent', cursor: 'pointer', fontWeight: 'bold' }}>-</button>
                    <span style={{ padding: '0 10px', fontWeight: 'bold' }}>{quantity}</span>
                    <button onClick={() => setQuantity(prev => prev + 1)} style={{ padding: '6px 12px', border: 'none', background: 'transparent', cursor: 'pointer', fontWeight: 'bold' }}>+</button>
                  </div>
                  <button onClick={() => handleAddToCart(selectedProduct, quantity)} style={{ flex: 1, padding: '10px 16px', backgroundColor: '#130352', color: '#fff', border: 'none', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>
                    Add to Cart
                  </button>
                </div>

                <div style={{ borderTop: '1px solid #f3f4f6', paddingTop: '12px' }}>
                  <h4 style={{ fontSize: '14px', fontWeight: 'bold', color: '#374151', marginBottom: '6px' }}>Product Description</h4>
                  <p style={{ fontSize: '14px', color: '#4b5563', lineHeight: '1.5', margin: 0 }}>{selectedProduct.description || 'No detailed description available.'}</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Products;
